using System;using System.Diagnostics;using System.Windows;using System.Windows.Automation;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Markup;using System.Windows.Media;using System.Windows.Threading;
internal static class SuiteScroll {
 public static DockPanel Wrap(ScrollViewer scroll,Func<string,string>? translate=null){var host=new DockPanel{LastChildFill=true};var button=new Button();var glyph=new TextBlock();DockPanel.SetDock(button,Dock.Bottom);host.Children.Add(button);host.Children.Add(scroll);Attach(scroll,button,glyph,translate);return host;}
 public static void Attach(ScrollViewer scroll,Button button,TextBlock glyph,Func<string,string>? translate=null){_=new Controller(scroll,button,glyph,translate??(value=>value));}
 sealed class Controller {
  readonly ScrollViewer scroll;readonly Button button;readonly TextBlock glyph;readonly Func<string,string> translate;readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(16)};readonly Stopwatch watch=new();double from,target;
  public Controller(ScrollViewer scroll,Button button,TextBlock glyph,Func<string,string> translate){this.scroll=scroll;this.button=button;this.glyph=glyph;this.translate=translate;scroll.VerticalScrollBarVisibility=ScrollBarVisibility.Hidden;scroll.HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled;scroll.PanningMode=PanningMode.VerticalOnly;scroll.CanContentScroll=false;button.Height=button.MinHeight=20;button.MinWidth=0;button.Padding=new Thickness(0);button.Margin=new Thickness(0,2,0,0);button.HorizontalAlignment=HorizontalAlignment.Stretch;button.Background=Brushes.Transparent;button.BorderThickness=new Thickness(0);button.Template=(ControlTemplate)XamlReader.Parse("<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='Button'><Border x:Name='Surface' Background='Transparent'><ContentPresenter HorizontalAlignment='Center' VerticalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='Surface' Property='BorderBrush' Value='{DynamicResource {x:Static SystemColors.HighlightBrushKey}}'/><Setter TargetName='Surface' Property='BorderThickness' Value='1'/></Trigger><Trigger Property='IsPressed' Value='True'><Setter Property='Opacity' Value='0.65'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='0.35'/></Trigger></ControlTemplate.Triggers></ControlTemplate>");glyph.FontFamily=new FontFamily("Segoe Fluent Icons");glyph.FontSize=16;button.Content=glyph;button.Click+=(_,_)=>Move();scroll.ScrollChanged+=(_,_)=>Update();scroll.Loaded+=(_,_)=>Update();scroll.PreviewMouseWheel+=(_,_)=>timer.Stop();scroll.PreviewKeyDown+=(_,_)=>timer.Stop();scroll.PreviewTouchDown+=(_,_)=>timer.Stop();scroll.Unloaded+=(_,_)=>timer.Stop();timer.Tick+=(_,_)=>Tick();Update();}
  void Update(){bool end=scroll.VerticalOffset>=scroll.ScrollableHeight-1;button.IsEnabled=scroll.ScrollableHeight>1;glyph.Text=end?"\uE70E":"\uE70D";string name=translate(end?"Voltar ao início":"Rolar para baixo");button.ToolTip=name;AutomationProperties.SetName(button,name);}
  void Move(){from=scroll.VerticalOffset;target=from>=scroll.ScrollableHeight-1?0:Math.Min(scroll.ScrollableHeight,from+scroll.ViewportHeight*.75);timer.Stop();if(!SystemParameters.ClientAreaAnimation){scroll.ScrollToVerticalOffset(target);return;}watch.Restart();timer.Start();}
  void Tick(){double t=Math.Min(1,watch.Elapsed.TotalMilliseconds/180);scroll.ScrollToVerticalOffset(from+(target-from)*(1-Math.Pow(1-t,3)));if(t>=1)timer.Stop();}
 }
}

